public class BitsTour {
    static final int READ = 1, WRITE = 1 << 1, EXECUTE = 1 << 2;   // one bit per permission

    static String bits(int x, int width) {
        String s = Integer.toBinaryString(x);
        return "0".repeat(Math.max(0, width - s.length())) + s;
    }

    public static void main(String[] args) {
        int perms = READ | WRITE;                                   // set two flags
        System.out.println("perms = " + bits(perms, 3) + " (read+write)");
        System.out.println("can execute? " + ((perms & EXECUTE) != 0));
        perms |= EXECUTE;                                           // grant
        perms &= ~WRITE;                                            // revoke
        System.out.println("after grant x, revoke w: " + bits(perms, 3));

        for (int n : new int[]{64, 96, 1}) {
            System.out.println(n + " is a power of two? " + (n > 0 && (n & (n - 1)) == 0)
                    + ", set bits: " + Integer.bitCount(n) + ", lowest set bit: " + (n & -n));
        }

        int[] values = {7, 3, 9, 3, 7};
        int single = 0;
        for (int v : values) single ^= v;                           // pairs cancel out
        System.out.println("the value without a pair: " + single);
    }
}

public class BitwiseOperators {
    static String b8(int x) {
        return String.format("%8s", Integer.toBinaryString(x & 0xFF)).replace(' ', '0');
    }

    static String b32(int x) {
        return String.format("%32s", Integer.toBinaryString(x)).replace(' ', '0');
    }

    public static void main(String[] args) {
        int a = 12, b = 10;
        System.out.println("a      = " + b8(a) + " = " + a);
        System.out.println("b      = " + b8(b) + " = " + b);
        System.out.println("a & b  = " + b8(a & b) + " = " + (a & b));
        System.out.println("a | b  = " + b8(a | b) + " = " + (a | b));
        System.out.println("a ^ b  = " + b8(a ^ b) + " = " + (a ^ b));
        System.out.println("a << 2 = " + b8(a << 2) + " = " + (a << 2));
        System.out.println("a >> 2 = " + b8(a >> 2) + " = " + (a >> 2));
        System.out.println("~a     = " + b32(~a) + " = " + ~a);

        int neg = -16;
        System.out.println("-16        = " + b32(neg));
        System.out.println("-16 >> 2   = " + b32(neg >> 2) + " = " + (neg >> 2));
        System.out.println("-16 >>> 28 = " + b32(neg >>> 28) + " = " + (neg >>> 28));
        System.out.println("-1         = " + b32(-1));
        System.out.println("MIN_VALUE  = " + b32(Integer.MIN_VALUE));
        System.out.println("-7 == ~7 + 1? " + (-7 == ~7 + 1));
        System.out.println("(13 & 1) == 0? " + ((13 & 1) == 0) + "  (13 is odd)");
    }
}

import java.util.ArrayList;
import java.util.List;

public class BitMasks {
    static final String[] DAYS = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};

    static String show(int mask) {
        List<String> names = new ArrayList<>();
        for (int i = 0; i < 7; i++) if ((mask & (1 << i)) != 0) names.add(DAYS[i]);   // test bit i
        String bits = String.format("%7s", Integer.toBinaryString(mask)).replace(' ', '0');
        return bits + " " + names;
    }

    public static void main(String[] args) {
        int gym = (1 << 0) | (1 << 2) | (1 << 4);          // Mon, Wed, Fri
        System.out.println("start:      " + show(gym));
        gym |= 1 << 5;                                     // set Sat
        System.out.println("set Sat:    " + show(gym));
        gym &= ~(1 << 2);                                  // clear Wed
        System.out.println("clear Wed:  " + show(gym));
        gym ^= 1 << 0;                                     // toggle Mon (off)
        System.out.println("toggle Mon: " + show(gym));
        gym ^= 1 << 0;                                     // toggle Mon (on again)
        System.out.println("toggle Mon: " + show(gym));

        int work = 0b0011111;                              // Mon..Fri
        System.out.println("gym & work: " + show(gym & work) + ", " + Integer.bitCount(gym & work) + " days");
        System.out.println("gym & ~work: " + show(gym & ~work & 0b1111111));

        String[] snacks = {"apple", "chips", "nuts", "juice"};
        int[] price = {2, 3, 4, 5};
        int n = snacks.length, count = 0;
        StringBuilder affordable = new StringBuilder();
        for (int m = 0; m < (1 << n); m++) {               // every subset of n items
            int total = 0;
            for (int i = 0; i < n; i++) if ((m >> i & 1) == 1) total += price[i];
            count++;
            if (total == 7) {
                List<String> picked = new ArrayList<>();
                for (int i = 0; i < n; i++) if ((m >> i & 1) == 1) picked.add(snacks[i]);
                affordable.append(picked).append(' ');
            }
        }
        System.out.println(count + " subsets of " + n + " snacks; costing exactly 7: " + affordable.toString().trim());
    }
}

public class PowerOfTwo {
    static String bin(int x) { return Integer.toBinaryString(x); }

    static boolean isPowerOfTwo(int n) { return n > 0 && (n & (n - 1)) == 0; }

    static int nextPowerOfTwo(int n) {           // smallest power of two >= n, for 1 <= n <= 2^30
        int x = n - 1;
        x |= x >> 1;                             // copy the highest 1 bit
        x |= x >> 2;                             // into every lower position
        x |= x >> 4;
        x |= x >> 8;
        x |= x >> 16;
        return x + 1;
    }

    public static void main(String[] args) {
        for (int n : new int[]{1, 6, 16, 40, 1024, 0}) {
            System.out.printf("%5d = %-12s power of two? %-5s", n, bin(n), isPowerOfTwo(n));
            if (n > 0) {
                System.out.printf(" n&(n-1) = %-12s n&-n = %-5d next power = %d", bin(n & (n - 1)), n & -n, nextPowerOfTwo(n));
            }
            System.out.println();
        }
        int x = 1003;
        System.out.println("1003 % 8 = " + (x % 8) + ", 1003 & 7 = " + (x & 7));
        System.out.println("clearing the lowest bit repeatedly: ");
        for (int v = 44; v != 0; v &= v - 1) System.out.println("  " + bin(v));
    }
}

public class XorProperties {
    public static void main(String[] args) {
        int[] values = {4, 1, 2, 1, 2, 7, 4};
        int single = 0;
        StringBuilder steps = new StringBuilder();
        for (int v : values) {
            single ^= v;
            steps.append(single).append(' ');
        }
        System.out.println("running XOR: " + steps.toString().trim() + " -> unpaired value " + single);

        int[] nums = {3, 0, 1, 5, 2};             // 0..5 with one missing
        int missing = nums.length;                // start with n
        for (int i = 0; i < nums.length; i++) missing ^= i ^ nums[i];
        System.out.println("missing from 0..5: " + missing);

        int a = 29, b = 42;
        a ^= b;
        b ^= a;
        a ^= b;
        System.out.println("after XOR swap: a = " + a + ", b = " + b);

        int x = 0b10110, y = 0b10010;
        int diff = x ^ y;
        System.out.println("10110 ^ 10010 = " + Integer.toBinaryString(diff) + ": they differ in "
                + Integer.bitCount(diff) + " bit(s), at position " + Integer.numberOfTrailingZeros(diff));
        System.out.println("4 ^ 4 = " + (4 ^ 4) + ", 9 ^ 0 = " + (9 ^ 0) + ", 5 ^ 3 ^ 5 = " + (5 ^ 3 ^ 5));
    }
}

import java.util.Arrays;

public class BitCounting {
    static int loops;

    static int naive(int n) {
        int count = 0;
        loops = 0;
        while (n != 0) {
            count += n & 1;
            n >>>= 1;                 // logical shift: also works for negative numbers
            loops++;
        }
        return count;
    }

    static int kernighan(int n) {
        int count = 0;
        loops = 0;
        while (n != 0) {
            n &= n - 1;               // clear the lowest set bit
            count++;
            loops++;
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println("     n   naive(loops)  kernighan(loops)  bitCount");
        for (int n : new int[]{0b1011, 0b1000000000000001, 255, -1}) {
            int a = naive(n), la = loops;
            int b = kernighan(n), lb = loops;
            System.out.printf("%6d %6d (%2d) %10d (%2d) %10d%n", n, a, la, b, lb, Integer.bitCount(n));
        }
        int[] bits = new int[16];
        for (int i = 1; i < 16; i++) bits[i] = bits[i >> 1] + (i & 1);   // reuse a smaller answer
        System.out.println("bits[0..15] = " + Arrays.toString(bits));
        System.out.println("parity of 0b1011: " + (Integer.bitCount(0b1011) & 1) + " (odd)");
    }
}

